import React from 'react';

const Testimonials = () => {
  const testimonials = [
    {
      name: "Sarah Johnson",
      role: "CEO, TechStart Inc.",
      content: "Clarix transformed our customer service with AI automation. We reduced response times by 80% and increased customer satisfaction scores significantly.",
      avatar: "👩‍💼"
    },
    {
      name: "Michael Chen",
      role: "Operations Director, GrowthCo",
      content: "The AI workflow they built for our sales team has been game-changing. We're closing 40% more deals while our team focuses on high-value activities.",
      avatar: "👨‍💼"
    },
    {
      name: "Emily Rodriguez",
      role: "Marketing Manager, InnovateLab",
      content: "Clarix's AI consulting helped us implement cutting-edge marketing automation. Our campaign performance improved by 250% in just two months.",
      avatar: "👩‍💻"
    }
  ];

  return (
    <div className="pg" id="page-testimonials">
      <div className="sec">
        <div style={{ textAlign: 'center', maxWidth: '600px', margin: '0 auto 4rem' }}>
          <span className="lbl reveal">Testimonials</span>
          <h1 className="dp reveal d1" style={{ marginTop: '.5rem' }}>
            What our clients<br />
            <span className="gr">say about us.</span>
          </h1>
          <p className="blg reveal d2" style={{ marginTop: '.9rem' }}>
            Real results from real businesses using AI to transform their operations.
          </p>
        </div>

        <div className="tgrid">
          {testimonials.map((testimonial, index) => (
            <div key={index} className="tcard">
              <div className="tavatar">{testimonial.avatar}</div>
              <div className="tbody">
                <p className="tcontent">"{testimonial.content}"</p>
                <div className="tauthor">
                  <div className="tname">{testimonial.name}</div>
                  <div className="trole">{testimonial.role}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Testimonials;
